'use strict';
const D=window.WORTWEG_DATA,C=WortwegCore.makeCore(D),{levels,dayKey,shuffle}=WortwegCore,KEY='wortweg.v1';
let S=WortwegCore.fresh(),storageOK=true,quiz=null,flash=null,lastActivity=Date.now(),tick=Date.now(),route='/',timerDirty=false;
try{const raw=localStorage.getItem(KEY);if(raw)S=C.validate(JSON.parse(raw));}catch(e){storageOK=false;}
const $=s=>document.querySelector(s),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),enc=encodeURIComponent;
function save(){try{localStorage.setItem(KEY,JSON.stringify(S));storageOK=true;}catch(e){storageOK=false;toast('记录暂时无法保存，请到设置导出备份。');}badge();}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500);}
function badge(){$('#due-badge').textContent=C.due(S).length+Object.values(S.mistakes).filter(m=>!m.resolved).length;}
const tag=l=>`<span class="tag ${String(l).toLowerCase()}">${E(l)}</span>`,levelTags=w=>(w.levels||[w.senses?.[0]?.level]).filter(Boolean).map(tag).join(' '),bar=n=>`<div class="progress"><span style="width:${Math.max(0,Math.min(100,n))}%"></span></div>`,link=(url,t,cls='button')=>`<a class="${cls}" href="${url}">${t}</a>`,stages=['A1.1','A1.2','A2.1','A2.2','B1.1','B1.2','B2.1','B2.2'],unitStage=u=>u.id.split('-')[0];
const minutes=n=>n<60?`${Math.floor(n)} 分钟`:`${Math.floor(n/60)} 小时 ${Math.floor(n%60)} 分钟`;
const estimate=us=>{const e=C.estimate(us,S);return e.high?`${e.low}–${e.high} 天`:'已完成';};
function head(t,sub='',action=''){return `<div class="page-head"><div><div class="eyebrow">DEUTSCH LERNEN · A1 — B2</div><h1>${t}</h1>${sub?`<p class="muted" style="margin-bottom:0">${sub}</p>`:''}</div>${action}</div>`;}
function unitCard(u){const p=C.progress(u,S);return `<a class="unit-card" href="#/grammar/${u.id}"><div class="row">${tag(u.level)}<span class="tag stage-tag">${unitStage(u)}</span><span class="small muted">${String(u.number).padStart(2,'0')} / 16</span></div><h3>${E(u.title)}</h3><div class="meta">${E(u.subtitle)}</div>${bar(p.complete?100:0)}<div class="row small"><span>${p.complete?'✓ 小测已通过':C.course(S).current?.id===u.id?'当前学习单元':'可自由查阅'}</span><span>${p.quiz===null?'尚未小测':`小测 ${Math.round(p.quiz)}%`} ↗</span></div></a>`;}
function home(){let u=C.course(S).current||D.units.at(-1);const due=C.due(S),errors=Object.values(S.mistakes).filter(m=>!m.resolved).length,today=S.days[dayKey()]?.total||0,completed=C.course(S).count,mastered=Object.values(S.senses).filter(s=>s.status==='mastered').length;
return head('今天，也离德语更近一步。','从一次复习开始，让学过的知识留下来。',`<span class="date">${new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date())}</span>`)+`<div class="stats"><div class="stat"><span class="small">今日学习</span><strong><span id="today-min">${Math.floor(today/60)}</span><small>分钟</small></strong><div class="small">每日目标 ${S.settings.dailyMinutes} 分钟</div></div><div class="stat"><span class="small">今日待复习</span><strong>${due.length+errors}<small>项</small></strong><div class="small">${due.length} 个义项 · ${errors} 道错题</div></div><div class="stat"><span class="small">已掌握义项</span><strong>${mastered}<small>/ ${Object.keys(C.senses).length}</small></strong><div class="small">每个词义独立记录</div></div><div class="stat"><span class="small">连续通过单元</span><strong>${completed}<small>/ ${D.units.length}</small></strong><div class="small">预计剩余 ${estimate(D.units)}</div></div></div><div class="columns"><section><div class="panel hero"><div class="eyebrow">CONTINUE LEARNING · 继续学习</div><p>${unitStage(u)} · ${u.level} · 第 ${String(u.number).padStart(2,'0')} 单元</p><h2>${E(u.title)}</h2><p class="muted">${E(u.subtitle)}</p>${link('#/grammar/'+u.id,'进入本单元 →')}<span class="level-big" aria-hidden="true">${u.level}</span></div><div class="section-title"><h2>你的学习地图</h2>${link('#/grammar','查看全部 ↗','text-link')}</div><div class="level-grid">${levels.map(l=>{const us=D.units.filter(x=>x.level===l),n=us.filter(x=>C.progress(x,S).complete).length;return `<a class="level-card" href="#/grammar?level=${l}"><b>${l}</b><span class="small muted">${{A1:'建立基础',A2:'连接表达',B1:'独立沟通',B2:'深入表达'}[l]}</span>${bar(n/16*100)}<span class="small">${n} / 16 单元</span></a>`;}).join('')}</div><div class="section-title" style="margin-top:26px"><h2>本周学习节奏</h2><span class="small muted">仅计活跃学习时间</span></div><div class="panel"><div class="chart">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const mins=(S.days[dayKey(d)]?.total||0)/60;return `<div class="bar-item"><span>${Math.floor(mins)}m</span><div class="bar" style="height:${Math.min(85,Math.max(3,mins/S.settings.dailyMinutes*75))}px"></div><span>${['日','一','二','三','四','五','六'][d.getDay()]}</span></div>`;}).join('')}</div></div></section><aside><div class="panel"><div class="section-title"><h2>今天的学习清单</h2><span class="tag">TODAY</span></div><ul class="checklist"><li><span class="circle">1</span><div><b>唤醒学过的单词</b><div class="small muted">${due.length?`${due.length} 个义项已到复习时间`:'从词典选择第一个学习义项'}</div></div></li><li><span class="circle">2</span><div><b>把错题真正弄懂</b><div class="small muted">${errors} 道错题等待重练</div></div></li><li><span class="circle">3</span><div><b>完成一个小目标</b><div class="small muted">语法 → 背词 → 单元小测</div></div></li></ul>${link('#/review','开始今日复习 →','button primary')}<p class="small muted" style="margin-top:14px">短时间，多次回顾。比一次背很久更容易坚持。</p></div><div class="panel"><div class="eyebrow">SO GUT WIE GESCHAFFT</div><h3>两种进度怎么看？</h3><p class="small muted">课程位置：从 A1 起连续通过的小测，成绩需 ≥85%。<br>完整掌握：小测 ≥85%、重点词义掌握 ≥80%、本单元错题全部复习。</p><p class="small muted">所有单元可随时查阅。预计天数依据剩余任务和每日投入估算，不代表 CEFR 考试达标时间。</p></div></aside></div>`;}
const aliases={};
D.words.forEach(w=>{[w.lemma,...(w.present||[]).map(x=>x.split(' ')[0]),w.past?.split(' ')[0],w.participle,w.plural,w.comparative,w.superlative?.replace('am ',''),...Object.values(w.conjugation||{}).flat().map(x=>x.split(' ')[0]),...(w.sourceForms||[]).map(f=>f.form)].filter(Boolean).forEach(a=>{const k=a.toLocaleLowerCase('de');if(!aliases[k])aliases[k]=[];if(!aliases[k].includes(w.id))aliases[k].push(w.id);});});
Object.entries({büchern:'Buch',kindern:'Kind',guten:'gut',gute:'gut',gutes:'gut',guter:'gut',neuen:'neu',neue:'neu',wärmsten:'warm',besten:'gut',hätte:'haben',hätten:'haben',wäre:'sein',wärst:'sein',sei:'sein',seien:'sein',könnte:'können',könnten:'können',würde:'werden',würden:'werden',möchte:'mögen',möchten:'mögen',studierenden:'Student'}).forEach(([a,id])=>aliases[a]=[id]);
// Studierende and Student are related but are not inflectional equivalents.
delete aliases.studierenden;
function de(text){return E(text).replace(/[A-Za-zÄÖÜäöüß]+/g,t=>`<button class="lookup" data-lookup="${t}" lang="de">${t}</button>`);}
function table(rows){return `<div class="table-wrap"><table><thead><tr>${rows[0].map(c=>`<th scope="col">${E(c)}</th>`).join('')}</tr></thead><tbody>${rows.slice(1).map(r=>`<tr>${r.map(c=>`<td>${E(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function stateButtons(id){const s=S.senses[id]||{};return `<div class="state-buttons" aria-label="辅助记忆标记，不影响熟练度">${[['unknown','不认识'],['familiar','有印象'],['mastered','已掌握']].map(([v,t])=>`<button data-rate="${E(id)}" data-status="${v}" class="${s.selfMark===v?'chosen':''}" aria-pressed="${s.selfMark===v}">${t}</button>`).join('')}<button data-focus="${E(id)}" class="favorite ${s.focus?'active':''}" aria-pressed="${!!s.focus}">${s.focus?'★':'☆'} 重点</button></div>`;}
function favoriteButton(id,grammar=false){const on=(grammar?S.grammarFavorites:S.favorites).includes(id);return `<button class="favorite icon ${on?'active':''}" data-favorite="${E(id)}" data-grammar="${grammar}" aria-label="${on?'取消':'添加'}收藏" aria-pressed="${on}">${on?'★':'☆'}</button>`;}
function wordCard(w){return `<article class="word-card"><div class="row"><div>${levelTags(w)} <span class="small muted">${E(w.pos)}</span><h3><a href="#/word/${enc(w.id)}">${E(w.article?w.article+' ':'')}${E(w.lemma)}</a></h3></div>${favoriteButton(w.id)}</div><p>${w.senses.map(s=>E(s.zh)).join('；')}</p><div class="row small muted" style="margin-top:12px"><span>${w.senses.length} 个义项 · ${w.type||(w.plural?`复数 ${E(w.plural)}`:w.pos)}</span><a class="text-link" href="#/word/${enc(w.id)}">查看词条 →</a></div></article>`;}
function grammarPage(id,query){if(!id){const l=query.get('level')||'all',course=C.course(S);return head('语法学习地图',`连续通过 ${course.count} / ${D.units.length} 单元 · 所有单元可自由查阅`)+`<div class="tabs">${['all',...levels,...stages].map(x=>link('#/grammar'+(x==='all'?'':'?level='+x),x==='all'?'全部单元':x,'button '+(x===l?'active':''))).join('')}</div><p class="muted">课程按 A1.1 → A1.2 → A2.1 → A2.2 → B1.1 → B1.2 → B2.1 → B2.2 推进；小测达到 85% 才会推动当前学习位置，所有单元仍可自由查阅。</p><div class="unit-grid">${D.units.filter(u=>l==='all'||u.level===l||unitStage(u)===l).map(unitCard).join('')}</div>`;}
 const u=C.units[id];if(!u)return missing();S.lastUnit=id;save();const p=C.progress(u,S),ix=D.units.indexOf(u);
 return `<article class="lesson">${head(E(u.title),`${unitStage(u)} · ${u.level} · 第 ${u.number} 单元 · ${p.complete?'小测已通过':'可自由查阅'}`,favoriteButton(id,true))}<p class="intro">${E(u.subtitle)}</p><nav class="lesson-nav">${link('#/grammar/'+id+'?section=rules','语法讲解')}${link('#/flash?unit='+id,'单元背词')}${link('#/quiz/'+id,'单元测试 →','button primary')}</nav><section class="grammar-feature"><div class="eyebrow">本单元核心语法</div><h2>先看本章范围</h2><p>${E(u.rule)}</p>${u.table?table(u.table):''}</section>${(u.sections||[]).map((x,i)=>`<section class="panel grammar-section"><span class="eyebrow">${String(i+1).padStart(2,'0')} · GRAMMATIK</span><h2>${E(x.title)}</h2>${x.paragraphs.map(t=>`<p>${E(t)}</p>`).join('')}${x.tables?.length?x.tables.map(table).join(''):x.table?table(x.table):''}${x.examples?.length?'<div class="eyebrow grammar-example-label">例句</div>':''}${(x.examples||[]).map(([ex,zh])=>`<div class="example"><p class="de" lang="de">${de(ex)}</p><button type="button" class="phrase-audio" data-speak="${E(ex)}" aria-label="播放例句">🔊 播放例句</button><p>${E(zh)}</p></div>`).join('')}</section>`).join('')}<div class="panel"><h2>易错点与小测例句</h2><div class="note"><b>重点辨析</b><p>${E(u.pitfall)}</p></div>${u.examples.map((e,i)=>{const sentence=e.prompt.split(' (')[0].replace('___',e.answer);return `<div class="example"><div class="eyebrow">BEISPIEL ${i+1}</div><div class="de" lang="de">${de(sentence)}</div><button type="button" class="phrase-audio" data-speak="${E(sentence)}" aria-label="播放例句">🔊 播放例句</button><p>${E(e.translation)}</p><p class="muted">${E(e.explanation)}</p></div>`;}).join('')}<button data-read="${u.id}" class="${S.units[id]?.read?'chosen':''}">${S.units[id]?.read?'✓ 已读过本单元':'标记已读'}</button><p class="small muted">阅读标记只记录回顾状态；课程位置由连续通过的小测决定。</p></div><section class="panel"><h2>本单元词汇 · ${u.focus.length} 个</h2><p class="muted">按词性和本章语境整理；动词变化表只在相关语法章节作为知识补充出现。</p>${(u.vocabulary||[{title:'相关词汇',words:u.focus}]).map(g=>`<h3 class="vocab-group-title">${E(g.title)}</h3><div class="word-grid">${g.words.map(id=>wordCard(C.words[id])).join('')}</div>`).join('')}<div style="margin-top:20px">${link('#/flash?unit='+u.id,'背本单元词汇 →','button primary')}</div></section><div class="panel unit-completion"><h2>单元进度与完整掌握</h2><p class="${p.complete?'status-good':'muted'}">${p.complete?'✓ 小测已通过；重测不会取消已有通过记录。':'小测达到 85% 后，本单元计入课程进度。'}</p><ul class="completion-list"><li class="${p.complete?'done':''}">小测 ≥85%：${p.quiz===null?'尚未测试':Math.round(p.quiz)+'%'}</li><li class="${p.ratio>=.8?'done':''}">重点词义掌握 ≥80%：${p.mastered}/${p.total}（${Math.round(p.ratio*100)}%）</li><li class="${p.errors===0?'done':''}">错题全部复习：${p.errors} 道待复习</li></ul><p class="${p.ready?'status-good':'small muted'}">${p.ready?'✓ 已达到本单元完整掌握标准。':'课程位置只按小测推进；词汇和错题继续独立复习。'}</p>${link('#/quiz/'+u.id,'开始随机小测 →','button primary')}</div><div class="row wrap">${ix?link('#/grammar/'+D.units[ix-1].id,'← 上一单元'):link('#/grammar','← 学习地图')}${ix<D.units.length-1?link('#/grammar/'+D.units[ix+1].id,'下一单元 →'):link('#/grammar','返回地图 →')}</div></article>`;
}
function morphology(w){
 if(w.conjugation){const c=w.conjugation,persons=['ich','du','er / sie / es','wir','ihr','sie / Sie'];
 const block=(title,cols,desc,open=false)=>`<details class="tense-group" ${open?'open':''}><summary>${title}</summary><p class="muted">${desc}</p>${table([['人称',...cols.map(x=>x[1])],...persons.map((p,i)=>[p,...cols.map(x=>c[x[0]][i])])])}</details>`;
 return `<h2>动词变位 · 直陈式与虚拟式</h2><p>${E(w.type)} · ${E(w.pattern)}</p><div class="principal-parts" lang="de">${E(w.lemma)} → ${E(w.present[2])} → ${E(w.past)} → ${E((w.auxiliary==='sein'?'ist':'hat')+' '+w.participle)}</div>
 ${block('① 直陈式：现在与过去',[['present','Präsens 现在时'],['past','Präteritum 过去时'],['perfect','Perfekt 完成时']],'叙述现实情况。过去时常见于书面叙事；sein、haben 和情态动词在口语中也经常用过去时。',true)}
 ${block('② 直陈式：过去完成与将来',[['pluperfect','Plusquamperfekt'],['future','Futur I'],['futurePerfect','Futur II']],'过去完成时表示过去某时点之前的事；将来时也可表达推测；将来完成时表示将来某时点前已完成，或推测过去。')}
 ${block('③ 第一虚拟式 · Konjunktiv I',[['ki','现在 / 同时'],['kiPast','过去 / 先发生'],['kiFuture','将来']],'主要用于正式转述。形式与直陈式相同时，可视语境改用第二虚拟式或 würde 形式；它本身不表示转述内容是假的。',true)}
 ${block('④ 第二虚拟式 · Konjunktiv II',[['kii','现在 / 将来的假设'],['kiiPast','非现实过去'],['would','würde + 不定式']],'表达假设、愿望或委婉请求。弱变化动词的简单形式常与过去时相同，此时通常更常用 würde + 不定式。sein、haben 和情态动词常直接用 wäre、hätte、könnte 等。')}
 <div class="note">${E(w.conjugationNote)}</div>${(w.conjugationExamples||[]).map(([ex,zh])=>`<div class="example"><p class="de" lang="de">${de(ex)}</p><p>${E(zh)}</p></div>`).join('')}
 <div class="row wrap">${link('#/grammar/A2.1-05','过去时讲解')}${link('#/grammar/B1.1-07','第二虚拟式讲解')}${link('#/grammar/B2.1-01','第一虚拟式讲解')}</div>`;
 }
 if(w.article&&w.plural&&w.genitive){const a=w.article,weak=w.weakNoun||a==='der'&&['Student','Nachbar'].includes(w.id),ob=w.oblique||(weak?w.genitive:w.lemma),plural=w.plural==='—'?null:w.plural,dp=plural&&!/[ns]$/.test(plural)?plural+'n':plural;return `<h2>名词形式与格</h2><p>${w.pluralOnly?'仅复数':{der:'阳性 · Maskulinum',die:'阴性 · Femininum',das:'中性 · Neutrum'}[a]} · ${weak?'弱变化名词':'随冠词和格一起记忆'}</p>${table([['格','单数','复数'],['Nominativ',w.pluralOnly?'—':a+' '+w.lemma,plural?'die '+plural:'通常无复数'],['Akkusativ',w.pluralOnly?'—':(a==='der'?'den':a)+' '+ob,plural?'die '+plural:'—'],['Dativ',w.pluralOnly?'—':(a==='die'?'der':'dem')+' '+ob,plural?'den '+dp:'—'],['Genitiv',w.pluralOnly?'—':(a==='die'?'der':'des')+' '+w.genitive,plural?'der '+plural:'—']])}<p class="small muted">不可数义与可数义的复数范围可能不同，按义项使用。</p>`;}
 if(w.comparative&&w.comparative!=='—')return `<h2>比较与用法</h2>${table([['原级','比较级','最高级'],[w.lemma,w.comparative,w.superlative]])}<p>${E(w.type||'')}。${w.pos==='形容词'?'作前置定语时按冠词、性、数、格添加词尾；作表语时通常不变格。':'副词不按定语形容词的方式变格。'}</p>`;
 return `<h2>词形与用法</h2><p>${E(w.pattern||'结合义项与语境使用。')}</p>${w.sourceForms?.length?table([['形式','语法信息'],...w.sourceForms.map(f=>[f.form,f.label])]):''}${w.pos==='动词'?external('https://www.verbformen.de/?w='+enc(w.lemma),'查看完整变位 ↗'):''}`;
}
function wordPage(id){const w=C.words[id];if(!w)return missing();return `<article class="lesson">${head(E((w.article?w.article+' ':'')+w.lemma),E(w.pos)+' · '+w.senses.length+' 个学习义项',favoriteButton(id))}<div class="panel">${soundButton(w)}<p class="small muted">${w.source?'拓展词库：阶段暂定，释义来自开放词典；可按自己的需要选择学习。':'课程词条：等级和学习型频率是编者的定性学习建议。'}${w.source?` ${external(w.source,'释义来源 ↗')}`:''}</p>${w.senses.map((x,i)=>`<section class="sense"><div class="row wrap"><span>${tag(x.level)} <span class="tag">${E(x.frequency)}</span></span><span class="small muted">义项 ${i+1} · 熟练度 ${S.senses[x.id]?.proficiency||0}%</span></div><div class="sense-reading"><div class="sense-meaning"><h3>${E(x.zh)}</h3>${x.pattern?`<p lang="de">${E(x.pattern)}</p>`:''}</div><aside class="sentence-panel"><span class="eyebrow">例句巩固</span>${x.example?`<div class="de" lang="de">${de(x.example)}</div><button type="button" class="phrase-audio" data-speak="${E(x.example)}" aria-label="播放例句">🔊 播放整句例句</button><p class="muted">${E(x.translation)}</p>${x.contextOnly?'<p class="small muted">语境联想例句：请按整句理解，可能涉及本词的其他用法。</p>':''}${x.exampleSource?`<a class="small text-link" href="${E(x.exampleSource)}" target="_blank" rel="noopener">例句来源 ↗</a>`:''}`:`<p class="muted">本义项的中文例句尚待补充。</p>${external('https://www.dwds.de/wb/'+enc(w.lemma),'查看德语例句 ↗')}`}</aside></div>${associationMap(w,x)}<details><summary>辅助标记与备注</summary>${stateButtons(x.id)}${noteEditor(x.id)}</details><p class="small muted">${reviewDate(x.id)}</p>${link('#/flash?word='+enc(w.id)+'&start=1','练习这个词 →','button primary')}</section>`).join('')}</div><div class="panel">${morphology(w)}${w.note?`<div class="note">${E(w.note)}</div>`:''}</div><div class="panel"><h2>继续查证与关联学习</h2><div class="row wrap">${external('https://www.dwds.de/wb/'+enc(w.lemma),'DWDS 德德释义 ↗')}${external('https://www.duden.de/suchen/dudenonline/'+enc(w.lemma),'Duden 查词 ↗')}</div><div class="tabs" style="margin-top:18px">${D.units.filter(u=>u.focus.includes(id)).map(u=>link('#/grammar/'+u.id,u.level+' · '+E(u.title))).join('')}</div></div></article>`;}
function dictionary(query){const q=query.get('q')||'',l=query.get('level')||'all',status=query.get('state')||'all';return head('一本词典，连起全部学习。',`${D.words.length} 个精选词条 · ${Object.keys(C.senses).length} 个独立义项`,link('#/flash','进入背词模式 →','button primary'))+`<form id="dictionary-filter" class="filters"><label><span class="visually-hidden">搜索词典</span><input type="search" name="q" placeholder="搜索德语、变位或中文释义…" value="${E(q)}"></label><label><span class="visually-hidden">学习等级</span><select name="level">${['all',...levels].map(x=>`<option value="${x}" ${l===x?'selected':''}>${x==='all'?'全部等级':x}</option>`).join('')}</select></label><label><span class="visually-hidden">学习状态</span><select name="state">${[['all','全部状态'],['unknown','不认识'],['familiar','有印象'],['mastered','已掌握'],['focus','我的重点'],['new','尚未学习']].map(([v,t])=>`<option value="${v}" ${status===v?'selected':''}>${t}</option>`).join('')}</select></label></form><p class="small muted" id="dict-count"></p><div class="word-grid" id="dictionary-results"></div>`;}
function filterWords(q,l,status){const eligible=D.words.filter(w=>w.senses.some(s=>(l==='all'||s.level===l)&&(status==='all'||status==='focus'&&S.senses[s.id]?.focus||status==='new'&&!S.senses[s.id]?.status||S.senses[s.id]?.status===status)));return WortwegCore.rankWords(eligible,q);}
function updateDictionary(){const f=$('#dictionary-filter');if(!f)return;const fdata=new FormData(f),q=String(fdata.get('q')||'').trim(),ws=filterWords(q,fdata.get('level'),fdata.get('state')),exact=q&&ws.length&&WortwegCore.searchRank(ws[0],q)===0;$('#dict-count').textContent=exact?'已找到完全一致的词条，只显示该结果。':`找到 ${ws.length} 个词条，已按与输入内容的接近程度排序。等级和状态按同一义项筛选。`;$('#dictionary-results').innerHTML=ws.length?ws.slice(0,100).map(wordCard).join(''):empty('没有匹配的词条','试试词语原形、相近拼写或中文释义。');}
const empty=(t,s)=>`<div class="empty"><b>${t}</b>${s}</div>`;
const missing=()=>head('没有找到这个页面')+link('#/','返回今日学习','button primary');
function external(url,text){return `<a class="button" href="${E(url)}" target="_blank" rel="noopener noreferrer">${text}</a>`;}
function showLookup(token){const ids=C.words[token]?[token]:aliases[token.toLocaleLowerCase('de')]||[];$('#word-preview').innerHTML=ids.length?ids.map(id=>{const w=C.words[id];return `<h2 class="modal-title">${E(w.article?w.article+' ':'')}${E(w.lemma)}</h2><p class="small muted">${E(w.pos)}${ids.length>1?' · 此词形可能对应多个词条':''}</p>${w.senses.map(s=>`<p>${tag(s.level)} ${E(s.zh)}</p>`).join('')}<p class="small">${w.present?E(w.present[1]+' · '+w.present[2]+' · '+w.past+' · '+w.participle):w.plural?E('复数 '+w.plural+' · 属格 '+w.genitive):E(w.comparative?[w.comparative,w.superlative].join(' · '):w.pattern||'')}</p>${link('#/word/'+enc(id),'查看完整词条 →','button primary')}`;}).join('<hr>'):`<h2 class="modal-title">${E(token)}</h2><p>本地精选词典暂未收录这个词形。请在德德词典核对原形和含义。</p>${external('https://www.dwds.de/wb/'+enc(token),'在 DWDS 查询 ↗')}`;$('#word-dialog').showModal();if(ids.length===1){$('#word-preview').insertAdjacentHTML('afterbegin',soundButton(C.words[ids[0]]));pronounce(ids[0],true);}}
function review(){const ids=C.due(S),errors=Object.entries(S.mistakes).filter(([,m])=>!m.resolved),hour=S.settings.reviewHour??4,next=new Date();next.setDate(next.getDate()+1);next.setHours(hour,0,0,0);return head('每日复习','作答后立即更新待复习数量；新任务在设定时间进入队列。')+`<div class="panel"><form id="review-settings"><div class="form-row"><label for="review-hour">每天几点刷新复习</label><select id="review-hour" name="hour">${Array.from({length:24},(_,h)=>`<option value="${h}" ${h===hour?'selected':''}>${String(h).padStart(2,'0')}:00</option>`).join('')}</select><button class="primary">保存刷新时间</button></div></form><p class="small muted">按设备当地时间。次日刷新：${next.toLocaleString('zh-CN')}。仅到期的词进入队列，未完成任务继续保留；即使届时没有打开网页，再次打开时也会更新。</p></div><div class="columns"><div class="panel"><h2>到期单词 <span class="tag">${ids.length} 个义项</span></h2>${ids.length?`<p class="muted">优先安排答错与较生疏的词。正确作答后立即移出当前到期列表；答错的词 10 分钟后再次提醒。</p>${link('#/flash?due=1','开始单词复习 →','button primary')}<div class="stack" style="margin-top:20px">${ids.slice(0,12).map(id=>`<div class="row"><a href="#/word/${enc(C.senses[id].word.id)}">${E(C.senses[id].word.lemma)} · ${E(C.senses[id].zh)}</a>${tag(C.senses[id].level)}</div>`).join('')}</div>`:empty('当前到期词汇已完成','后续任务将在各自到期日的刷新时间出现。')}${!ids.length?link('#/flash','选择词库学新词 →'):''}</div><div class="panel"><h2>错题回顾 <span class="tag">${errors.length} 题</span></h2><p class="muted">单元错题重新答对后立即标记已复习。未答对的题继续保留，不会因刷新而消失。</p>${errors.length?link('#/quiz/review','重练待复习错题 →','button primary'):empty('暂无待复习错题','之后的小测错题会自动收录。')}</div></div><div class="panel"><h2>熟练度与复习间隔</h2><p>德译中和中译德各自积累。两个方向都在不同复习日独立答对至少 3 次，才标记已掌握；同方向 20 小时内重复答对不会刷高熟练度。答错会降低积累，10 分钟后重练。</p><p>答对后，根据两个方向中较弱一项的积累，安排到 1、2、4、8、16 或 30 天后的刷新时间。手动的“不认识 / 有印象 / 已掌握”以及重点、备注只辅助学习，不会直接改变熟练度。</p></div>`;}
function mistakes(){const entries=Object.entries(S.mistakes).sort((a,b)=>(a[1].resolved-b[1].resolved)||(b[1].last-a[1].last));return head('错过的题，值得再看一次。',`${entries.filter(([,m])=>!m.resolved).length} 题待复习 · ${entries.filter(([,m])=>m.resolved).length} 题已复习`,entries.some(([,m])=>!m.resolved)?link('#/quiz/review','重练错题 →','button primary'):'')+(entries.length?entries.map(([id,m])=>{const q=C.questions[id];return `<div class="panel"><div class="row wrap">${tag(C.units[m.unit].level)}<span class="small ${m.resolved?'status-good':'status-bad'}">${m.resolved?'✓ 已重新答对':'待复习'} · 累计错 ${m.count} 次</span></div><p class="de" lang="de" style="margin:14px 0">${E(q.prompt)}</p><details><summary>查看答案与中文解析</summary><p><b>${E(q.answer)}</b></p><p>${E(q.explanation)}</p></details><div class="row wrap">${link('#/grammar/'+m.unit,'回到语法单元','text-link')}${q.word?link('#/word/'+enc(q.word),'查看关联词条','text-link'):''}${link('#/quiz/review?question='+enc(id),'重新练这题 →')}</div></div>`;}).join(''):empty('错题本还是空的','完成一次单元小测，做错的题会自动收录。'));}
function flashPage(query){
 const scoped=!!(query.get('unit')||query.get('due')||query.get('word'));
 if(!query.get('start')&&!scoped)return head('选择今天要背的词库','可同时选择多个阶段；每个词义分别练习德译中与中译德。')+`<form id="flash-setup" class="panel"><div class="level-grid">${levels.map(l=>`<label class="library-option"><input type="checkbox" name="levels" value="${l}" ${S.settings.wordLevels.includes(l)?'checked':''}><b>${l}</b><span>${D.words.filter(w=>w.senses.some(s=>s.level===l)).length} 个词条</span></label>`).join('')}</div><div class="form-row" style="margin-top:24px"><label>每轮词义数 <select name="count">${[10,20,30,50].map(n=>`<option ${S.settings.wordCount===n?'selected':''}>${n}</option>`).join('')}</select></label><label>练习方向 <select name="mode"><option value="both" ${S.settings.wordMode==='both'?'selected':''}>双向：先德译中，再中译德</option><option value="de-zh" ${S.settings.wordMode==='de-zh'?'selected':''}>看德语写中文</option><option value="zh-de" ${S.settings.wordMode==='zh-de'?'selected':''}>看中文写德语</option></select></label></div><p class="muted">优先安排到期词，再学新词。熟练度由实际作答积累；手动标记与备注只辅助记忆。两个方向都要在不同复习日答对，才能达到已掌握。</p><button class="primary">开始背词 →</button></form>`;
 const key=query.toString();if(!flash||flash.key!==key){let ids=query.get('word')&&C.words[query.get('word')]?C.words[query.get('word')].senses.map(s=>s.id):query.get('unit')&&C.units[query.get('unit')]?C.focus(C.units[query.get('unit')]):query.get('due')?C.due(S):Object.keys(C.senses).filter(id=>S.settings.wordLevels.includes(C.senses[id].level));const now=Date.now();ids=[...shuffle(ids.filter(id=>S.senses[id]?.due<=now)),...shuffle(ids.filter(id=>!S.senses[id]?.practice)),...shuffle(ids.filter(id=>S.senses[id]?.practice&&S.senses[id]?.due>now))];ids=[...new Set(ids)].slice(0,S.settings.wordCount);const mode=S.settings.wordMode||'both';const cards=mode==='both'?[...ids.map(id=>({id,dir:'de-zh'})),...shuffle(ids).map(id=>({id,dir:'zh-de'}))]:ids.map(id=>({id,dir:mode}));flash={key,cards,index:0,shown:false,hinted:false,result:null,correct:0};}
 const card=flash.cards[flash.index];if(!card)return head('本轮练习完成',`${flash.cards.length} 次练习 · ${flash.correct} 次独立答对`)+`<div class="panel"><p>已保存双向练习结果。答错的词会更快进入复习；同一天反复答同一个词不会刷高掌握等级。</p>${link('#/flash','重新选择词库','button primary')} ${link('#/review','查看每日复习')}</div>`;
 const x=C.senses[card.id],w=x.word,toZh=card.dir==='de-zh',record=S.senses[card.id]||{};
 return head(toZh?'看德语，写出中文意思。':'看中文，写出德语单词。',`${flash.index+1} / ${flash.cards.length} · ${toZh?'德 → 中':'中 → 德'} · ${x.level}`)+`<div class="panel flashcard"><div class="row">${tag(x.level)}<span class="small">当前熟练度 ${record.proficiency||0}%</span></div><div class="recall-prompt" lang="${toZh?'de':'zh'}">${E(toZh?(w.article?w.article+' ':'')+w.lemma:x.zh)}</div>${toZh?soundButton(w):''}<p class="small muted">${toZh?'填写一个符合该词义的中文表达。':'词性：'+E(w.pos)+'；请保留 ä、ö、ü、ß。名词冠词可一同填写。'}</p><form id="recall-form"><label class="visually-hidden" for="recall-answer">你的答案</label><input id="recall-answer" name="answer" autocomplete="off" autocapitalize="off" spellcheck="false" value="${E(flash.answer||'')}" ${flash.result?'disabled':''} placeholder="输入答案…">${!flash.result?'<button class="primary" style="margin-top:16px">检查答案</button>':''}</form>
 ${flash.result?`<div class="feedback ${flash.result.ok?'':'wrong'}"><b>${flash.result.ok?'✓ 独立答对':flash.result.correct?'已看提示，本次不增加熟练度':'这次还没答对'}</b><p>${E(w.lemma)} · ${E(x.zh)}</p>${!flash.result.correct?'<p class="small">离线判分只识别已收录译法；你的同义表达若未被识别，可备注保留。</p>':''}</div>`:''}
 ${flash.shown||flash.result?`<div class="answer sense-reading"><div class="sense-meaning"><strong>${E(w.lemma)} · ${E(x.zh)}</strong>${!toZh?soundButton(w):''}</div><aside class="sentence-panel"><p class="de" lang="de">${de(x.example||'')}</p>${x.example?`<button type="button" class="phrase-audio" data-speak="${E(x.example)}" aria-label="播放例句">🔊 播放整句例句</button>`:''}<p>${E(x.translation||'')}</p><p class="small">${E(x.pattern||'')}</p></aside></div><details><summary>辅助标记与我的备注</summary>${stateButtons(card.id)}${noteEditor(card.id)}</details><details class="tense-group"><summary>展开完整词形${w.pos==='动词'?'与虚拟式变位':''}</summary>${morphology(w)}</details>`:`<button data-flip="1" class="text-link" style="margin-top:18px">看提示（本次不增加熟练度）</button>`}
 ${associationMap(w,x)}
 ${flash.result?'<button class="primary" data-flash-next="1" style="margin-top:20px">下一题 →</button>':''}</div><div class="row wrap">${link('#/word/'+enc(w.id),'查看完整词条','text-link')}<button data-flash-skip="1">跳过 →</button>${link('#/flash','重新选择词库')}</div>`;
}
function quizPage(id,query){const key=id+'?'+query.toString();if(!quiz||quiz.key!==key){let qs;if(id==='review'){const qid=query.get('question');qs=qid&&C.questions[qid]&&S.mistakes[qid]?[C.questions[qid]]:shuffle(Object.entries(S.mistakes).filter(([,m])=>!m.resolved).map(([k])=>C.questions[k])).slice(0,10);}else if(C.units[id])qs=shuffle([...shuffle(C.bank(C.units[id]).filter(q=>q.source==='grammar')).slice(0,4),...shuffle(C.bank(C.units[id]).filter(q=>q.source==='vocabulary'&&q.prompt.trim())).slice(0,3)]);else return missing();quiz={key,id,qs:qs.map(q=>({...q,options:shuffle([...new Set([q.answer,...q.choices])])})),answers:{},result:null};}const rev=id==='review';if(!quiz.qs.length)return head('暂无待复习错题')+link('#/review','返回复习');return head(rev?'再试一次，把错题学会。':'本单元随机小测',rev?'重新答对后，错题会标记为已复习。':`${C.units[id].level} · ${C.units[id].title} · ${quiz.qs.length} 题 · ≥85% 达标`)+`<div class="panel"><form id="quiz-form">${quiz.qs.map((q,i)=>{const res=quiz.result?.results.find(r=>r.id===q.id);return `<section class="quiz-question"><span class="eyebrow">${String(i+1).padStart(2,'0')} / ${quiz.qs.length} · ${q.kind==='input'?'填写空缺内容':'选择正确答案'}</span><p class="de" lang="de">${E(q.prompt).replace(/\n/g,'<br>')}</p>${q.kind==='input'?`<label><span class="visually-hidden">第 ${i+1} 题答案</span><input name="${E(q.id)}" value="${E(quiz.answers[q.id]||'')}" autocomplete="off" autocapitalize="off" spellcheck="false" ${quiz.result?'disabled':''} placeholder="填写空格中缺少的完整形式…"></label><p class="small muted">填写句中缺少的词或词形；请保留 ä / ö / ü / ß。判分忽略首尾空格、句末标点和大小写。</p>`:`<div class="options">${q.options.map((o,j)=>`<label><input type="radio" name="${E(q.id)}" value="${E(o)}" ${quiz.answers[q.id]===o?'checked':''} ${quiz.result?'disabled':''}><span>${String.fromCharCode(65+j)}. ${E(o)}</span></label>`).join('')}</div>`}${res?`<div class="feedback ${res.ok?'':'wrong'}"><b>${res.ok?'✓ 正确':'✕ 还需要复习'} · ${E(q.answer)}</b><p style="margin:6px 0">${E(q.explanation)}</p><p class="small muted">${E(q.translation)}</p>${link('#/grammar/'+q.unit,'查看相关语法','text-link')}${q.word?' · '+link('#/word/'+enc(q.word),'查看词典','text-link'):''}</div>`:''}</section>`;}).join('')}<div style="margin-top:24px">${quiz.result?`<h2>${quiz.result.correct} / ${quiz.result.total} · ${Math.round(quiz.result.score)}%</h2><p>${rev?'答对的错题已标记为复习完成。':quiz.result.score>=85?'✓ 本单元小测已通过，课程位置会按连续通过单元推进。':'未达 85%，请根据解析复习后再试。'}</p><button type="button" data-new-quiz="1">${rev?'继续重练待复习题':'换一组再练'}</button> ${link(rev?'#/mistakes':'#/grammar/'+id,rev?'返回错题本':'返回本单元','button primary')}`:'<button type="submit" class="primary">提交并查看解析 →</button><p class="small muted">提交前请完成所有题目；未提交不会计入成绩。</p>'}</div></form></div>`;}
function favorites(){return head('留给下一次的好内容。','收藏词条和语法页；词义“重点”标签在词典中单独筛选。')+`<div class="section-title"><h2>收藏的词条</h2></div><div class="word-grid">${S.favorites.length?S.favorites.map(id=>wordCard(C.words[id])).join(''):empty('还没有收藏词条','点击词条右上角的星标即可收藏。')}</div><div class="section-title" style="margin-top:25px"><h2>收藏的语法</h2></div><div class="unit-grid">${S.grammarFavorites.length?S.grammarFavorites.map(id=>unitCard(C.units[id])).join(''):empty('还没有收藏语法','在语法页标题旁点击星标即可。')}</div>`;}
function search(){return head('找到你想弄懂的内容。','支持德语词形、中文释义、语法标题与正文。')+`<label><span class="visually-hidden">全站搜索</span><input id="global-search" type="search" placeholder="例如：比较级、dachte、反身动词…" autofocus></label><div id="search-results" style="margin-top:24px">${empty('从一个问题开始','输入关键词，即时搜索本地内容。')}</div>`;}
function listening(){const resources=[['A1–B2','Goethe · 免费德语练习','按等级选择听力、视频与播客练习。','https://www.goethe.de/ueben'],['A1–B2','DW · Deutsch lernen','进入 DW 德语学习门户，选择 Nicos Weg 或适合自己的课程。','https://www.dw.com/deutschlernen'],['A2','Goethe · A2 听力模拟','考试格式的听力练习；先读题，再按说明听音频。','https://bfu.goethe.de/a2_mod_2MX5/hoeren.php'],['A1–B2','Goethe · 发音训练','有针对性的发音与听辨训练，具体使用条件以资源页面为准。','https://www.goethe.de/de/m/spr/ueb/ast.html']];return head('让耳朵也跟上学习。','选一段适合自己的音频，听懂比听得多更重要。')+`<div class="unit-grid">${resources.map(([l,t,d,url])=>`<a class="panel resource" href="${url}" target="_blank" rel="noopener noreferrer"><span class="arrow">↗</span><span class="tag">${l}</span><h3 style="margin-top:14px">${t}</h3><p class="muted">${d}</p><span class="text-link">打开资源</span></a>`).join('')}</div><div class="panel"><h2>一次听力，分三遍完成</h2><ol><li>第一遍不看文本，抓住人物、场景和主题。</li><li>第二遍带着问题听，记下关键词。</li><li>最后对照原文查词，再跟读两三句。</li></ol><p class="small muted">这些是外部资源入口，需联网；音视频版权属于原提供者，本 ZIP 不包含其媒体。离开本站后不会继续累计本站学习时长。DW 页面在核查环境中限制自动访问，已用 DW 官方课程介绍核对入口用途。</p></div>`;}
function settings(){const today=S.days[dayKey()]||{};return head('照顾好你的学习记录。','本地保存，无需注册；换设备前先导出备份。')+`<div class="panel"><h2>每日学习目标</h2><form id="settings-form"><div class="form-row"><label for="daily-minutes">每天投入</label><input id="daily-minutes" name="minutes" type="number" min="5" max="300" step="1" value="${S.settings.dailyMinutes}"><span>分钟</span><button class="primary">保存目标</button></div></form><p class="small muted">计时仅在页面可见、窗口有焦点且最近 60 秒内有点击、键盘或滚动活动时累计；后台和长时间闲置暂停。同源多个标签页只有焦点页累计。</p>${table([['今日类别','时长'],...['grammar','words','quiz','review'].map(k=>[{grammar:'语法',words:'词典/背词',quiz:'小测',review:'复习'}[k],minutes((today[k]||0)/60)])])}<p class="small muted">课程预计天数依据尚未通过单元的剩余阅读分钟和小测任务，再除以每日目标或最近 7 个自然日平均。区间取约 0.8–1.4 倍；只表示本站任务，不表示考试能力。</p></div><div class="panel"><h2>备份与迁移</h2><p class="${storageOK?'muted':'status-bad'}">${storageOK?'当前可使用浏览器本地存储。':'当前存储不可用或旧记录无法读取；请导出当前记录再检查浏览器设置。'}</p><div class="row wrap"><button class="primary" data-export="1">导出学习记录 JSON</button><label class="button">导入备份<input id="import-file" class="visually-hidden" type="file" accept="application/json,.json"></label></div><p class="small muted" style="margin-top:16px">导入前会检查格式并显示记录摘要，确认后替换此浏览器的当前记录。清理浏览器数据、隐私模式结束或更换访问地址可能丢失本地记录。没有自动跨设备同步。</p></div>`;}
function about(){return head('内容边界与参考资料','准确优先，明确区分语言事实与学习建议。')+`<div class="panel"><h2>这套网站包含什么</h2><p>${D.units.length} 个语法单元（每级 16 个，分为 A1.1/A1.2、A2.1/A2.2、B1.1/B1.2、B2.1/B2.2），${D.words.length} 个词条，${Object.keys(C.senses).length} 个学习义项，${Object.keys(C.questions).length} 道单元题库题。每次小测随机抽取 4 道语法题和 3 道词义题。单元页面均可独立打开和收藏。</p><p>这是覆盖 A1–B2 主要语法的自学工具与扩展词库，不是完整 CEFR 词汇全集、官方教材或考试通过保证。对口语、写作、真实听力的能力训练仍需结合外部课程与反馈。</p><h3>分级和学习型频率</h3><p>等级是编者建议的引入顺序。核心常用、常用、场景常用、书面常用是定性的学习标签，不对应百分比，不声称来自 Goethe 分级或任何语料库测量。</p><h3>原创与引用</h3><p>中文讲解、例句和题目为本项目编写；没有整段复制 Goethe 受版权保护的词表、文章或音频。以下资料用于核对规则与资源用途，外部词典保留自己的全部权利。</p><ul><li><a class="text-link" target="_blank" rel="noopener" href="https://grammis.ids-mannheim.de/terminologie/400">IDS grammis · Konjunktiv I</a></li><li><a class="text-link" target="_blank" rel="noopener" href="https://grammis.ids-mannheim.de/fragen/6829">IDS grammis · 间接引语中的语气选择</a></li><li><a class="text-link" target="_blank" rel="noopener" href="https://grammis.ids-mannheim.de/systematische-grammatik/929">IDS grammis · Werden-Passiv</a></li><li><a class="text-link" target="_blank" rel="noopener" href="https://grammis.ids-mannheim.de/progr%40mm/1695">IDS grammis · 助动词与被动完成时</a></li><li><a class="text-link" target="_blank" rel="noopener" href="https://www.duden.de/rechtschreibung/nehmen">Duden · nehmen 词形与义项</a></li><li><a class="text-link" target="_blank" rel="noopener" href="https://www.goethe.de/ueben">Goethe · 免费学习资源</a></li><li><a class="text-link" target="_blank" rel="noopener" href="https://static.dw.com/downloads/62764909/broschuere-dw-deutsch-lernen.pdf">DW · 官方课程介绍</a></li></ul><p class="small muted">资料核查：2026-09-07。已做结构和重点语言核查；未经过德语教师逐条审校。词形歧义会显示候选，未收录词会提示查外部词典，不会生成猜测释义。</p></div>`;}
function render(){const raw=location.hash.slice(1)||'/',parts=raw.split('?'),path=parts[0],query=new URLSearchParams(parts[1]||''),segments=path.split('/').filter(Boolean),page=segments[0]||'home',id=decodeURIComponent(segments[1]||'');route=path;if(page!=='quiz')quiz=null;if(page!=='flash')flash=null;if($('#word-dialog').open)$('#word-dialog').close();let html;
switch(page){case 'home':html=home();break;case 'grammar':html=grammarPage(id,query);break;case 'dictionary':html=dictionary(query);break;case 'word':html=wordPage(id);break;case 'review':html=review();break;case 'mistakes':html=mistakes();break;case 'flash':html=flashPage(query);break;case 'quiz':html=quizPage(id,query);break;case 'favorites':html=favorites();break;case 'search':html=search();break;case 'listening':html=listening();break;case 'settings':html=settings();break;case 'about':html=about();break;default:html=missing();}
$('#main').innerHTML=html;const navPage={word:'dictionary',flash:'dictionary',quiz:id==='review'?'mistakes':'grammar',search:'dictionary'}[page]||page;document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===navPage;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#breadcrumb').textContent='学习空间 / '+({home:'今天',grammar:'语法',dictionary:'词典',word:'词条',review:'每日复习',mistakes:'错题本',flash:'背词',quiz:'小测',favorites:'收藏',listening:'听力',settings:'设置',search:'搜索',about:'内容说明'}[page]||'');document.title=($('#main h1')?.textContent||'德语学习')+' · 小八的德语之路';if(page==='dictionary')updateDictionary();badge();injectVerbClassPanel(C.units[route.split('/')[2]]);injectProfile();injectQuizGuidance();updateAvatar();autoPronounce();}
function persistTime(){if(timerDirty){save();timerDirty=false;}}
function tally(){const now=Date.now(),elapsed=Math.min(5000,Math.max(0,now-tick))/1000;tick=now;if(document.hidden||!document.hasFocus()||now-lastActivity>60000)return;let cat=route.startsWith('/quiz/review')||route.startsWith('/review')||route.startsWith('/mistakes')?'review':route.startsWith('/quiz')?'quiz':route.startsWith('/grammar/')?'grammar':route.startsWith('/word/')||route.startsWith('/dictionary')||route.startsWith('/flash')?'words':null;if(!cat)return;const key=dayKey(),day=S.days[key]||(S.days[key]={total:0,grammar:0,words:0,quiz:0,review:0});day.total+=elapsed;day[cat]+=elapsed;const id=route.startsWith('/grammar/')?route.split('/')[2]:null;if(id&&C.units[id]){S.units[id]??={};S.units[id].seconds=(S.units[id].seconds||0)+elapsed;}timerDirty=true;if($('#today-min'))$('#today-min').textContent=Math.floor(day.total/60);}
function downloadJSON(){const blob=new Blob([JSON.stringify(S,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='wortweg-progress-'+dayKey()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出学习记录');}
async function importJSON(file){if(!file)return;try{if(file.size>5*1024*1024)throw Error('备份文件超过 5 MB');const parsed=JSON.parse(await file.text()),next=C.validate(parsed),count=Object.values(next.senses).filter(s=>s.status).length;if(!confirm(`此备份包含 ${count} 个已学习义项、${Object.keys(next.units).length} 个单元记录。\n将替换此浏览器当前学习记录。建议先导出当前记录。\n确认导入吗？`))return;S=next;save();render();toast('备份已导入');}catch(e){toast('导入失败：'+e.message);}}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;lastActivity=Date.now();if(b.classList.contains('skip')){e.preventDefault();$('#main').focus();return;}if(b.classList.contains('close')){$('#word-dialog').close();stopAudio();return;}if(b.dataset.lookup){showLookup(b.dataset.lookup);return;}if(b.dataset.favorite){const key=b.dataset.grammar==='true'?'grammarFavorites':'favorites',id=b.dataset.favorite,index=S[key].indexOf(id);if(index<0)S[key].push(id);else S[key].splice(index,1);save();b.classList.toggle('active',index<0);b.setAttribute('aria-pressed',String(index<0));b.setAttribute('aria-label',index<0?'取消收藏':'添加收藏');b.textContent=index<0?'★':'☆';if(route==='/favorites')render();return;}if(b.dataset.focus){const id=b.dataset.focus;S.senses[id]??={};S.senses[id].focus=!S.senses[id].focus;save();b.classList.toggle('active',S.senses[id].focus);b.setAttribute('aria-pressed',String(S.senses[id].focus));b.textContent=S.senses[id].focus?'★ 重点':'☆ 重点';return;}if(b.dataset.rate){const y=scrollY;C.rate(S,b.dataset.rate,b.dataset.status);save();render();if(route.startsWith('/word/'))scrollTo(0,y);return;}if(b.dataset.read){const id=b.dataset.read;S.units[id]??={};S.units[id].read=true;save();b.textContent='✓ 已读过本单元';toast('已记录阅读进度');return;}if(b.dataset.flip){if(flash){flash.hinted=true;flash.shown=true;render();}return;}if(b.dataset.flashSkip){advanceFlash();return;}if(b.dataset.newQuiz){quiz=null;render();return;}if(b.dataset.export){persistTime();downloadJSON();return;}});
document.addEventListener('input',e=>{lastActivity=Date.now();if(e.target.closest('#dictionary-filter'))updateDictionary();if(e.target.id==='global-search'){const q=e.target.value.trim().toLocaleLowerCase('de');if(!q){$('#search-results').innerHTML=empty('从一个问题开始','输入关键词，即时搜索本地内容。');return;}const us=D.units.filter(u=>[u.title,u.subtitle,u.rule,u.pitfall,u.level].join(' ').toLocaleLowerCase('de').includes(q)),ws=filterWords(q,'all','all');$('#search-results').innerHTML=`<h2>语法 · ${us.length}</h2><div class="unit-grid">${us.map(unitCard).join('')||empty('没有匹配语法','换个关键词试试。')}</div><h2 style="margin-top:24px">词条 · ${ws.length}</h2><div class="word-grid">${ws.slice(0,100).map(wordCard).join('')||empty('没有匹配词条','本地词库是精选内容，可从词条使用外部词典。')}</div>`;}if(e.target.closest('#quiz-form')&&quiz)quiz.answers[e.target.name]=e.target.value;});
document.addEventListener('change',e=>{if(e.target.closest('#dictionary-filter'))updateDictionary();if(e.target.id==='import-file')importJSON(e.target.files[0]);});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='quiz-form'&&quiz&&!quiz.result){const f=new FormData(e.target),answers={};for(const q of quiz.qs)answers[q.id]=String(f.get(q.id)||'');const missing=quiz.qs.find(q=>!answers[q.id].trim());if(missing){toast('请先完成所有题目。');document.getElementsByName(missing.id)[0]?.focus();return;}quiz.answers=answers;quiz.result=C.grade(S,C.units[quiz.id],quiz.qs,answers,quiz.id==='review');save();render();$('#quiz-form').lastElementChild.scrollIntoView({block:'center',behavior:'smooth'});}if(e.target.id==='settings-form'){const n=Number(new FormData(e.target).get('minutes'));if(!Number.isInteger(n)||n<5||n>300){toast('请输入 5–300 之间的整数');return;}S.settings.dailyMinutes=n;save();toast('每日目标已保存');}});
['pointerdown','keydown','scroll','touchstart'].forEach(type=>document.addEventListener(type,()=>{lastActivity=Date.now();},{passive:true}));
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){e.preventDefault();location.hash='/search';setTimeout(()=>$('#global-search')?.focus(),0);}});
window.addEventListener('hashchange',()=>{tally();persistTime();render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
window.addEventListener('blur',()=>{tally();persistTime();});window.addEventListener('pagehide',()=>{tally();persistTime();});document.addEventListener('visibilitychange',()=>{if(document.hidden){persistTime();}tick=Date.now();});window.addEventListener('focus',()=>{try{const raw=localStorage.getItem(KEY);if(raw)S=C.validate(JSON.parse(raw));}catch(e){}tick=Date.now();lastActivity=Date.now();});window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{S=C.validate(JSON.parse(e.newValue));if(!quiz&&!flash)render();}catch(e){toast('另一窗口的记录无法读取。');}}});
setInterval(tally,1000);setInterval(persistTime,5000);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'search_german_learning',title:'搜索德语学习内容',description:'只读搜索本地词典与语法，并返回独立页面地址。',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input.query!=='string'||input.query.length>200)throw Error('query 必须为不超过 200 字的字符串');const q=input.query.trim().toLowerCase();return {words:filterWords(q,'all','all').slice(0,15).map(w=>({lemma:w.lemma,url:'#/word/'+enc(w.id)})),units:D.units.filter(u=>u.title.toLowerCase().includes(q)).map(u=>({title:u.title,url:'#/grammar/'+u.id}))};}})).catch(()=>{});}catch(e){}}

function profilePanel(){const n=S.settings.profileName||'小八',a=S.settings.profileAvatar||'学',img=S.settings.profileAvatarData||'';const preview=img?`<img class="profile-avatar profile-avatar-image" src="${E(img)}" alt="${E(n)} 的头像">`:`<span class="profile-avatar">${E(a)}</span>`;return `<section class="panel profile-panel"><div class="profile-preview">${preview}<div><h2>我的学习身份</h2><p class="muted">${E(n)} · 只保存在此设备</p></div></div><form id="profile-form"><div class="form-row"><label for="profile-name">显示名字</label><input id="profile-name" name="name" maxlength="30" value="${E(n)}" placeholder="例如：小八"></div><fieldset class="avatar-picker"><legend>头像</legend><div class="avatar-upload-row"><label class="button" for="profile-avatar-file">上传图片<input id="profile-avatar-file" name="avatarFile" type="file" accept="image/png,image/jpeg,image/webp,image/gif" class="visually-hidden"></label>${img?'<button type="button" data-clear-avatar="1">恢复文字头像</button>':''}<span class="small muted">PNG、JPG、WEBP 或 GIF，不超过 1 MB</span></div><p class="small muted">图片只保存在此浏览器，不会上传服务器。</p><div class="avatar-options">${['学','八','德','☆','●','☀'].map(x=>`<label><input type="radio" name="avatar" value="${x}" ${a===x&&!img?'checked':''}><span class="profile-avatar">${x}</span></label>`).join('')}</div></fieldset><button class="primary">保存个人资料</button></form></section>`;}
function injectProfile(){if(route!=='/settings')return;const main=$('#main');if(main&&!main.querySelector('#profile-form'))main.insertAdjacentHTML('afterbegin',profilePanel());}
function updateAvatar(){const av=document.querySelector('.avatar');if(!av)return;av.title=S.settings.profileName||'小八';if(S.settings.profileAvatarData){av.innerHTML=`<img src="${E(S.settings.profileAvatarData)}" alt="${E(S.settings.profileName||'小八')} 的头像">`;av.classList.add('avatar-image');}else{av.textContent=S.settings.profileAvatar||'学';av.classList.remove('avatar-image');}}

function perfectAuxiliaryPanel(u){
 const ws=(u.focus||[]).map(id=>C.words[id]).filter(w=>w?.pos==='动词').slice(0,22);
 const rows=ws.map(w=>[w.lemma,w.auxiliary==='sein'?'sein':'haben',w.participle||'—',`${w.auxiliary==='sein'?'bin':'habe'} ${w.participle||''}`,w.senses?.[0]?.zh||'']);
 return `<section class="perfect-guide"><h3>haben 和 sein：按动词用法判断</h3><div class="auxiliary-grid"><div><b>haben</b><p>及物动词、反身动词和大多数动作使用 <span lang="de">haben</span>：<span lang="de">Ich habe das Buch gelesen.</span></p></div><div><b>sein</b><p>表示位置移动或状态变化的不及物用法，以及 <span lang="de">bleiben、sein、werden</span>，通常使用 <span lang="de">sein</span>：<span lang="de">Ich bin nach Hause gegangen.</span></p></div></div><p class="small muted">同一个动词在不同义项中可能选择不同助动词，应按词条搭配判断。助动词按六个人称变化，Partizip II 放在句框末端。</p><h3>本章常见动词的完成时</h3>${table([['动词','助动词','Partizip II','ich 形式','中文提示'],...rows])}</section>`;
}
function verbClassPanel(u){
 const presentOnly=['A1.1-02','A1.1-06','A1.1-07','A1.2-04','A1.2-06'].includes(u.id);
 const presentRules={weak:'规则现在时：去掉 -en，再按六个人称添加 -e、-st、-t、-en、-t、-en。',mixed:'本章只观察这些动词的现在时人称形式；过去形式留到过去时章节。',strong:'部分强变化动词在 du 与 er/sie/es 现在时改变词干元音，其他人称通常保留原词干。',irregular:'sein、haben、werden 和情态动词的现在时需要按六个人称整组记忆。'};
 const perfectRules={weak:'弱变化动词的 Partizip II 通常为 ge- + 词干 + -(e)t，例如 gelernt、gearbeitet。',mixed:'混合变化的 Partizip II 会改变词干并以 -t 结尾，例如 gedacht、gebracht。',strong:'强变化动词的 Partizip II 多以 -en 结尾且可能改变词干，例如 gelesen、gegangen。',irregular:'sein、haben、werden 的 Partizip II 和助动词选择需要单独记忆。'};
 const fullRules={weak:'规则变化：现在时使用固定人称词尾；Präteritum 通常为词干 + -te，Partizip II 通常为 ge-…-t。',mixed:'混合变化：词干变化，同时保留弱变化的 -te / -t，如 denken–dachte–gedacht。',strong:'强变化：过去时改变词干，Partizip II 多为 ge-…-en；部分动词在 du 与 er/sie/es 现在时也换元音。',irregular:'特殊不规则：sein、haben、werden 和情态动词需要整组记忆。'};
 const rules=presentOnly?presentRules:u.id==='A1.2-05'?perfectRules:fullRules;
 const labels={weak:'规则变化 · 弱变化',mixed:'半规则变化 · 混合变化',strong:'不规则变化 · 强变化',irregular:'特殊不规则'};
 const people=['ich','du','er / sie / es','wir','ihr','sie / Sie'],stage=u.id;
 const forms={
  'A1.1-02':['present'],'A1.1-06':['present'],'A1.1-07':['present'],'A1.2-04':['present'],'A1.2-05':['present','participle','perfect'],'A1.2-06':['imperative'],
  'A2.1-05':['present','past','participle','perfect'],'A2.2-06':['present','future'],'A2.2-07':['present','participle'],
  'B1.1-05':['past','perfect','pluperfect'],'B1.1-06':['present','past','passive'],'B1.1-07':['present','kii'],
  'B1.2-01':['present','past','perfect','passive'],'B1.2-02':['present','kii','kiiPast'],'B1.2-08':['present','past','perfect','pluperfect','future'],'B2.1-01':['present','ki'],
  'B2.1-02':['present','kii','kiiPast'],'B2.1-03':['present','past','perfect','pluperfect','future','passive'],'B2.1-04':['present','infinitive']
 };
 const names={present:'Präsens 现在时',past:'Präteritum 过去时',participle:'Partizip II',perfect:'Perfekt 完成时',pluperfect:'Plusquamperfekt 过去完成时',future:'Futur I 将来时',ki:'Konjunktiv I 第一虚拟式',kii:'Konjunktiv II 第二虚拟式',kiiPast:'Konjunktiv II 过去非现实',passive:'Passiv 被动态',infinitive:'不定式结构',imperative:'Imperativ 命令式'};
 const keys=forms[stage]||['present'],passiveAux=['werde','wirst','wird','werden','werdet','werden'];
 if(stage==='A1.2-06'){
  const fixed={sein:['Sei!','Seid!','Seien Sie!'],haben:['Hab!','Habt!','Haben Sie!'],kommen:['Komm!','Kommt!','Kommen Sie!'],gehen:['Geh!','Geht!','Gehen Sie!'],lesen:['Lies!','Lest!','Lesen Sie!'],nehmen:['Nimm!','Nehmt!','Nehmen Sie!'],geben:['Gib!','Gebt!','Geben Sie!']};
  const ws=(u.focus||[]).map(id=>C.words[id]).filter(Boolean);return `<section class="verb-class"><h3>du、ihr 与 Sie 命令式</h3><p>du 形式省略主语和 -st；ihr 形式等于现在时 ihr 形式但省略 ihr；Sie 形式使用不定式词形 + Sie。sein 及部分强变化动词需要单独记忆。</p>${table([['动词','du','ihr','Sie'],...ws.map(w=>[w.lemma,...(fixed[w.id]||['—','—',w.lemma[0].toUpperCase()+w.lemma.slice(1)+' Sie!'])])])}</section>`;
 }
 const cell=(w,key,i)=>{const c=w.conjugation||{};if(key==='participle')return w.participle||'—';if(key==='passive'){if(['sein','haben','werden','bleiben','kommen','gehen','fahren'].includes(w.id)||w.type==='情态动词')return '—';return `${passiveAux[i]} ${w.participle||'Partizip II'}`;}if(key==='infinitive')return w.pattern||`zu + ${w.lemma}`;return c[key]?.[i]||w[key]?.[i]||'—';};
 return Object.keys(labels).map(cls=>{const ws=(u.focus||[]).map(id=>C.words[id]).filter(w=>w?.verbClass===cls);if(!ws.length)return '';return `<section class="verb-class"><h3>${labels[cls]}</h3><p>${rules[cls]}</p>${ws.slice(0,12).map(w=>{const preview=keys.map(k=>k==='present'?(w.conjugation?.present?.[2]||w.present?.[2]):k==='participle'?w.participle:null).filter(Boolean).join(' · ');return `<details class="verb-entry"><summary><span lang="de">${E(w.lemma)}</span><span class="small muted">${E(preview)}</span></summary>${table([['人称',...keys.map(k=>names[k])],...people.map((p,i)=>[p,...keys.map(k=>cell(w,k,i))])])}<p class="small muted">${link('#/word/'+enc(w.id),'打开完整词条与全部时态 →','text-link')}</p></details>`;}).join('')}</section>`;}).join('');
}
function injectVerbClassPanel(u){
 if(!route.startsWith('/grammar/')||!u)return;
 const verbUnits=['A1.1-02','A1.1-06','A1.1-07','A1.2-04','A1.2-05','A1.2-06','A2.1-05','A2.2-06','A2.2-07','B1.1-05','B1.1-06','B1.1-07','B1.2-01','B1.2-02','B1.2-08','B2.1-01','B2.1-02','B2.1-03','B2.1-04'];
 if(!verbUnits.includes(u.id))return;
 const target=document.querySelector('.grammar-feature');if(!target)return;
 const focus=(u.verbFocus||[]).filter(id=>C.words[id]?.pos==='动词' || C.words[id]?.type==='情态动词');
 const el=document.createElement('section');el.className='panel verb-classes';
 el.innerHTML=`<h2>${u.id==='A1.1-06'?'语法补充：情态动词六人称':'语法补充：本章涉及的动词变化'}</h2><p class="muted">该表属于本章语法知识，不计作本章词汇分类；只展示当前学习阶段需要的时态。完整范式保留在词条页。</p>${verbClassPanel({...u,focus})}${u.id==='A1.2-05'?perfectAuxiliaryPanel({...u,focus}):''}`;
 target.after(el);
}

function injectQuizGuidance(){if(!quiz)return;const form=$('#quiz-form');if(form&&!form.querySelector('.quiz-overview')){const intro=document.createElement('div');intro.className='quiz-overview';intro.innerHTML='<b>题目说明</b><span>填写题只填空格中缺少的完整词或词形。</span><span>选择题直接选择最符合句意和语法的答案。</span><span>提交后显示正确答案、中文翻译和解析。</span>';form.prepend(intro);}document.querySelectorAll('.quiz-question').forEach((el,i)=>{if(el.querySelector('.quiz-guide'))return;const q=quiz.qs[i];if(!q)return;const w=q.word&&C.words[q.word],guide=document.createElement('div');guide.className='quiz-guide';guide.innerHTML=`<b>考查内容</b><span>${q.source==='vocabulary'&&w?`${E((w.article?w.article+' ':'')+w.lemma)} · ${E(w.pos)}`:'本单元语法与词形'}</span>${w?`<a class="text-link" href="#/word/${enc(w.id)}">查看词条 ↗</a>`:''}`;el.querySelector('.de')?.after(guide);});}

document.addEventListener('submit',e=>{if(e.target.id!=='profile-form')return;e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')||'').trim().slice(0,30),avatar=String(f.get('avatar')||'学');S.settings.profileName=name||'小八';if(!S.settings.profileAvatarData&&['学','八','德','☆','●','☀'].includes(avatar))S.settings.profileAvatar=avatar;save();render();toast('个人资料已保存');});
document.addEventListener('change',e=>{if(e.target.name==='avatar'&&['学','八','德','☆','●','☀'].includes(e.target.value)){delete S.settings.profileAvatarData;S.settings.profileAvatar=e.target.value;save();render();toast('已切换文字头像');return;}if(e.target.id!=='profile-avatar-file'||!e.target.files?.[0])return;const file=e.target.files[0];if(file.size>1024*1024){toast('头像图片请控制在 1 MB 以内');e.target.value='';return;}const reader=new FileReader();reader.onload=()=>{S.settings.profileAvatarData=String(reader.result||'');save();render();toast('头像图片已保存');};reader.onerror=()=>toast('头像读取失败，请换一张图片');reader.readAsDataURL(file);});
document.addEventListener('click',e=>{if(!e.target.closest('[data-clear-avatar]'))return;delete S.settings.profileAvatarData;save();render();toast('已恢复文字头像');});

render();
if(!storageOK)toast('本地记录未能读取，请查看设置并备份学习记录。');
